SET IS_DELETED = 'Y',
CONTENT = '삭제된 메시지입니다',
MESSAGE_TYPE = 'TEXT'
WHERE MESSAGE_ID = #{messageId}
AND ROOM_ID = #{roomId}
AND SENDER_ID = #{userId}
AND IS_DELETED = 'N'

